  ],
  "confidence": "high",
  "narrative": "Starting from a high anchor based on the early-2026 IOM pace, the explicit updates push the estimate toward a near-certain crossing of 900 deaths by end-March. While SAR capacity and weather could dampen the toll, the current pace and push factors keep the posterior probability around 97%, with a narrow calibrated range.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Anchor probability drawn from the highest forecast anchor among the supplied forecasts (late February 2026 pace around 606 deaths); reference class is Central Mediterranean death tolls and early-year pace."
    },
    "factor_updates": [
      {
        "factor": "March 2026 crossing pace on the Central Mediterranean route (volume/attempt rate)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "With about 606 deaths by late February 2026, continuing at a similar pace into March implies end-March toll near or above 900, increasing the probability of surpassing 900 before April."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment in the Central Mediterranean",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Expanded SAR or safer navigation policies would save lives, reducing deaths and lowering the chance that the March total reaches 900."
      },
      {
        "factor": "Push factors from source regions driving more crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Worsening conditions in origin areas could increase crossing attempts, pushing deaths higher."
      },
      {
        "factor": "Weather/sea conditions in March 2026 on the Central Mediterranean",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "March sea conditions are variable and could either raise or lower crossing frequency; net directional effect uncertain."
      },
      {
        "factor": "Reporting completeness and IOM data revisions for 2026",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Improvements in death reporting or retroactive revisions could raise the counted toll, nudging the total upward."
      }
    ],
    "synthesis_rationale": "The 0.97 posterior results from anchoring on a high early-2026 pace and applying multiple factors with moderate impact in the same direction. While some factors pull down or neutralize the effect, the net calibration remains strongly upward due to the sustained pace; correlations among factors are acknowledged and incorporated to temper overconfidence, yielding a high but not absolute certainty."
  }
}

